// Converte gli allegati (binari) in lotti di massimo 5 documenti per Nokfi.
const TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const docs = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    if (!TYPES.includes(bin.mimeType)) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    docs.push({ name: bin.fileName || key, mime: bin.mimeType, data: buffer.toString('base64') });
  }
}
const batches = [];
for (let k = 0; k < docs.length; k += 5) batches.push({ json: { files: docs.slice(k, k + 5) } });
return batches;

// Una riga per fattura, con i controlli di Nokfi in colonne.
const rows = [];
for (const item of $input.all()) {
  for (const inv of item.json.invoices || []) {
    rows.push({ json: {
      file: inv.file_name, emittente: inv.issuer_name, nif_emittente: inv.issuer_nif,
      numero: inv.invoice_number, data: inv.invoice_date, scadenza: inv.due_date,
      imponibile: inv.base, aliquota_iva: inv.vat_rate, iva: inv.vat_amount, ritenuta: inv.irpf_amount, totale: inv.total,
      quadra: inv.checks.totals_ok ? 'sì' : 'NO', nif_valido: inv.checks.nif_valid ? 'sì' : 'NO',
      avvisi: (inv.warnings || []).map(w => w.message).join(' · ')
    } });
  }
}
return rows;
